{
  "a_sentences": [
    {
      "a_text": "Die Versicherten kritisieren in einer einzigen Satzformulierung die Kündigung ihres seit über 30 Jahren bewohnten Mietobjekts, obwohl die Vermieterin andere Mieter im benachbarten Objekt belässt.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Bei anwaltlicher Vertretung beider Parteien übt das Gericht Zurückhaltung aus, wie in einem ordentlichen Verfahren.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Ein unbefristeter Mietvertrag mit stillschweigender Verlängerung kann von jeder Partei auf den vertraglich vereinbarten Termin gekündigt werden, sofern die Kündigungsfrist eingehalten wird.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Angabe des Kündigungsgrundes ist keine Gültigkeitsvoraussetzung; dessen Fehlen bedeutet nicht zwingend eine Treuwidrigkeit.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Ein treuwidriger Kündigungsgrund liegt vor, wenn eine krass unangemessene Interessenabwägung zwischen dem Interesse des Mieters am Verbleib und dem Interesse des Vermieters an der Beendigung vorliegt.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Vorinstanz stellte fest, dass der Kündigungsgrund nicht angegeben wurde, er aber nachträglich mitgeteilt und nicht als vorgeschoben erachtet wurde.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz verneinte besonders nachteilige Folgen für die Versicherten.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt, dass keine krass unangemessene Interessenabwägung vorliegt, weshalb die Interessenabwägung nur bei der Prüfung einer Erstreckung des Mietverhältnisses erfolgt.",
      "b_propositions": ["P8"]
    }
  ]
}
